import java.io.IOException;
import java.net.*;
import java.util.Set;

public class SsrfSafeClient {
    private static final Set<String> ALLOWED_PROTOCOLS = Set.of("http", "https");

    /**
     * 防 DNS rebinding 的关键：校验和建连用同一个 IP，
     * 不给 JDK 底层二次 DNS 解析留时间窗。
     */
    public static HttpURLConnection openSafe(String url) throws IOException {
        URI uri = URI.create(url).normalize();
        if (!ALLOWED_PROTOCOLS.contains(uri.getScheme())) {
            throw new SecurityException("protocol not allowed: " + uri.getScheme());
        }

        String host = uri.getHost();
        // 一次性解析全部 IP（A + AAAA），避免 toctou
        InetAddress[] addrs = InetAddress.getAllByName(host);
        for (InetAddress a : addrs) {
            if (isBlocked(a)) {
                throw new SecurityException("blocked ip: " + a.getHostAddress());
            }
        }

        // 用已校验的 IP 字符串建连，绕开 JDK 内部二次 DNS 解析
        InetAddress chosen = addrs[0];
        URL realUrl = new URL(uri.getScheme(), chosen.getHostAddress(),
                uri.getPort(), uri.getRawPath());
        HttpURLConnection conn = (HttpURLConnection) realUrl.openConnection();
        conn.setRequestProperty("Host", host); // 保留原 Host 头（HTTPS SNI + 虚拟主机）
        conn.setInstanceFollowRedirects(false);  // 禁自动跟随，跳转后再次校验
        conn.setConnectTimeout(3000);
        conn.setReadTimeout(5000);
        return conn;
    }

    private static boolean isBlocked(InetAddress a) {
        return a.isLoopbackAddress()        // 127/8, ::1
            || a.isLinkLocalAddress()       // 169.254/16（含 AWS 元数据 169.254.169.254）
            || a.isSiteLocalAddress()       // 10/8, 172.16/12, 192.168/16
            || a.isAnyLocalAddress()        // 0.0.0.0
            || a.isMulticastAddress()
            || a.getHostAddress().startsWith("100.100."); // 阿里云元数据
    }
}
